        for c in range(w):
            if grid[r][c] not in (3, 9) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            nines = 0
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                nines += grid[x][y] == 9
